SELECT 'bb052843-6b25-4284-90f5-f3062b5e6582', id, 0, 'send_messages', '{"messages":[{"messageType":"flex","altText":"【現在地の確認です】無料期間は残り5日になりました","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#222222\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"無料期間 残り5日\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"現在地の確認です\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"FurimAutoです。\\n無料期間は残り5日になりました。\\n\\nいま、自分がどこまで来たか確認してみてください。\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true},{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#FFF6E5\",\"cornerRadius\":\"8px\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"✅ リサーチで売れるものが分かる（無料）\\n✅ 出品まわりの補助機能（無料）\\n⬜ 値下げ・再出品などの自動化（無料期間中に体験できます）\\n⬜ コピー出品での販路拡大\\n⬜ 併売の在庫管理\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"}]},{\"type\":\"text\",\"text\":\"正直にお伝えすると、基本のリサーチと出品まわりの機能は期間が終わっても無料のまま使えます。\\n\\n有料になるのは「自動化」から先です。\\n\\n残り5日。まだ試していない自動化があれば、今のうちに動かしてみてください。\\n\\n「使い方がよく分からない…」という方は、【Youtube動画講座】が近道です🎬\\n入門から上級まで、段階的に理解できます👇\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true,\"margin\":\"md\"},{\"type\":\"text\",\"text\":\"\\\"手放せるかどうか\\\"は、体験した人にしか分かりません。\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\",\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#FF0000\",\"action\":{\"type\":\"uri\",\"label\":\"Youtube動画講座を見る\",\"uri\":\"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG\"}}]}}"}]}', '{"remaining_days_gte":5,"remaining_days_lte":5}', 1, '残5日: 現在地の確認（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
